277→export async function stageStructuredIntegration(repoRoot, taskId, resultSha, opts = {}) {
278→  ensureBatonExcluded(repoRoot);
279→  if (!isClean(repoRoot)) throw mergeError('structured integration requires a clean main checkout', 'structured_main_dirty');
280→  let rightSha;
281→  try { rightSha = sh('git', ['rev-parse', '--verify', `${resultSha}^{commit}`], repoRoot); }
282→  catch (error) { throw mergeError('structured integration result is not a commit', 'structured_invalid_result', error); }
283→  const beforeSha = sh('git', ['rev-parse', 'HEAD'], repoRoot);
284→  try { sh('git', ['merge-base', '--is-ancestor', rightSha, beforeSha], repoRoot); throw mergeError('structured integration result is already contained by main', 'structured_already_integrated'); }
285→  catch (error) { if (error?.code === 'structured_already_integrated') throw error; }
286→  const mergeBaseSha = sh('git', ['merge-base', beforeSha, rightSha], repoRoot);
287→  const root = integrationRoot(repoRoot); mkdirSync(root, { recursive: true });
288→  const stagePath = join(root, `${taskId}-${randomBytes(4).toString('hex')}`);
289→  try { sh('git', ['worktree', 'add', '--detach', stagePath, beforeSha], repoRoot); }
290→  catch (error) { throw mergeError('structured integration stage could not be created', 'structured_stage_failed', error); }
291→  const classes = []; const resolutions = [];
292→  try {
293→    let mergeClean = true;
294→    try { gitFile(['-c', 'core.hooksPath=/dev/null', '-c', 'merge.conflictStyle=diff3', 'merge', '--no-verify', '--no-commit', '--no-ff', rightSha], stagePath, { encoding: 'utf8', stdio: 'pipe' }); }
295→    catch { mergeClean = false; }
296→    const unmergedRaw = gitFile(['diff', '--name-only', '--diff-filter=U', '-z'], stagePath, { encoding: 'utf8' });
297→    const conflictedPaths = unmergedRaw.split('\0').filter(Boolean);
298→    if (mergeClean) classes.push({ path: null, class: 'clean_textual' });
299→    else {
300→      if (conflictedPaths.length === 0) throw mergeError('Git merge failed without resolvable text conflicts', 'structured_merge_failed');
301→      if (!opts.resolver || typeof opts.resolver.resolve !== 'function') throw mergeError('structured merge resolver is unavailable', 'structured_tool_unavailable');
302→      if (!Number.isSafeInteger(opts.resolver.maxFileBytes) || opts.resolver.maxFileBytes <= 0) throw mergeError('structured resolver lacks a deployment-derived file ceiling', 'structured_policy_invalid');
303→      const realStagePath = realpathSync(stagePath);
304→      for (const relativePath of conflictedPaths) {
305→        const absolutePath = pathResolve(stagePath, relativePath); const within = pathRelative(stagePath, absolutePath);
306→        if (within === '..' || within.startsWith(`..${sep}`) || isAbsolute(within) || !existsSync(absolutePath) || !lstatSync(absolutePath).isFile()) throw mergeError(`unsupported structured conflict path: ${relativePath}`, 'structured_unsupported_path');
307→        const realConflictPath = realpathSync(absolutePath); const realWithin = pathRelative(realStagePath, realConflictPath);
308→        if (realWithin === '..' || realWithin.startsWith(`..${sep}`) || isAbsolute(realWithin)) throw mergeError(`structured conflict escapes stage: ${relativePath}`, 'structured_unsupported_path');
309→        const conflict = readFileSync(absolutePath); if (conflict.includes(0)) throw mergeError(`structured conflict is binary: ${relativePath}`, 'structured_binary_conflict');
310→        if (conflict.byteLength > opts.resolver.maxFileBytes) throw mergeError(`structured conflict exceeds file budget: ${relativePath}`, 'structured_file_too_large');
311→        const isolatedRoot = realpathSync(mkdtempSync(join(tmpdir(), 'baton-structured-conflict-'))); const isolatedName = basename(relativePath); const isolatedPath = join(isolatedRoot, isolatedName);
312→        let resolution; let merged;
313→        try {
314→          writeFileSync(isolatedPath, conflict, { mode: 0o600 });
315→          resolution = await opts.resolver.resolve({ cwd: isolatedRoot, relativePath: isolatedName, absolutePath: isolatedPath });
316→          if (resolution?.status === 'resolved') {
317→            if (!existsSync(isolatedPath) || !lstatSync(isolatedPath).isFile()) throw mergeError(`structured resolver replaced the candidate path: ${relativePath}`, 'structured_unsupported_path');
