393→  let registered = false;
394→
395→  const cleanup = async () => {
396→    if (registered || existsSync(dir)) {
397→      try {
398→        sh('git', ['worktree', 'remove', '--force', dir], repoRoot);
399→      } catch {
400→        rmSync(dir, { recursive: true, force: true });
401→      }
402→    }
