406→  // Source stays commit-fresh while explicitly configured installed dependencies are copied into
407→  // the sandbox. Never symlink/hardlink the main checkout: the pinned verification command must
408→  // not be able to mutate the orchestrator's toolchain through its dependency path. Any copy
409→  // failure removes and prunes the worktree before the error escapes.
410→  const copiedDependencies = [];
411→  try {
412→    sh('git', ['worktree', 'add', '--detach', ...(sparsePaths.length ? ['--no-checkout'] : []), dir, fullSha], repoRoot);
413→    registered = true;
