498→    for (const entry of readdirSync(mergeRoot)) {
499→      const fullDir = join(mergeRoot, entry);
500→      let isDir = false; try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
501→      if (!isDir) continue;
502→      try {
503→        try { sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot); }
504→        catch { rmSync(fullDir, { recursive: true, force: true }); }
505→        report.removedIntegrationDirs.push(fullDir);
