507→      } catch (err) { report.errors.push(`${entry}: ${err.message || err}`); }
508→    }
509→    try { if (readdirSync(mergeRoot).length === 0) rmSync(mergeRoot, { recursive: true, force: true }); } catch { /* best effort */ }
510→  }
511→
512→  const expected = new Set(expectedActiveTaskIds);
513→
514→  const wtRoot = join(repoRoot, '.baton', 'wt');
515→  if (existsSync(wtRoot)) {
516→    for (const entry of readdirSync(wtRoot)) {
517→      if (entry.endsWith('.meta.json')) continue;
518→      const fullDir = join(wtRoot, entry);
519→      let isDir = false;
520→      try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
521→      if (!isDir) continue;
522→      if (expected.has(entry)) continue;
523→      try {
524→        try {
525→          sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot);
526→        } catch {
527→          rmSync(fullDir, { recursive: true, force: true });
528→        }
529→        const metaFile = metaPathFor(repoRoot, entry);
530→        if (existsSync(metaFile)) rmSync(metaFile, { force: true });
531→        report.removedZombieDirs.push(fullDir);
532→        logEvent(opts, entry, 'worktree.reconciled', { dir: fullDir });
533→      } catch (err) {
534→        report.errors.push(`${entry}: ${err.message || err}`);
535→      }
536→    }
537→  }
538→
539→  // Note: `.baton/verify/*` sandboxes are intentionally NOT swept here. They are always
540→  // created and reaped synchronously by their own caller (referee/coordinator via
541→  // `sandbox.cleanup()`) within the same operation, so they never need boot-time zombie
542→  // detection, and sweeping them here would misattribute reconcile events away from the
543→  // taskId-scoped `worker` field callers rely on (red workers-trust#9).
544→  try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best-effort */ }
545→  return report;
546→}
