1→// worktree.mjs — git-worktree lifecycle mechanics. Everything shells out to a real
2→// `git` binary against a real repo — no git library, no mocking of git itself.
3→//
4→// D7 (spec/RECONCILIATION.md, authoritative) pins the coordinator's ONE dependency
5→// interface as exactly this module's exports: pinBaseSha, createFromBase, captureCommit,
6→// freshVerifySandbox, changedLines, reap, reconcile, listWorktrees (+ markStopped, which
7→// remains a real export per IMPLEMENTATION.md §3 W5 even though D7's literal list omits it).
8→//
9→// Everything this module creates lives under <repoRoot>/.baton/ — `.baton/wt/<taskId>`
10→// for a worker's own worktree, `.baton/verify/<label>-<suffix>` for a throwaway sandbox.
11→// The two directories are structurally namespaced apart (W1).
12→
13→import { execFileSync } from 'node:child_process';
14→import {
15→  cpSync, existsSync, mkdirSync, mkdtempSync, writeFileSync, readFileSync, rmSync, readdirSync, statSync, lstatSync, realpathSync,
16→} from 'node:fs';
17→import { tmpdir } from 'node:os';
18→import {
19→  basename, join, dirname, isAbsolute, sep, resolve as pathResolve, relative as pathRelative,
20→} from 'node:path';
21→import { randomBytes } from 'node:crypto';
