447→    if (!evidence || evidence.digest !== digest(operationalEvent) || evidence.kind !== 'integration.completed') return null;
448→    const nodeId = `decision:integrate:${taskId}:${operationalEvent.seq}`;
449→    const node = this._knowledgeNodes.get(nodeId);
450→    if (!node || node.promotion?.trigger !== 'integration') return null;
451→    const decisionEvent = this._events[node.observedSeq - 1];
452→    const driverEvent = this._events[node.observedSeq];
453→    const artifactEvent = this._events[node.observedSeq + 1];
454→    if (decisionEvent?.kind !== 'knowledge.promoted' || decisionEvent.payload?.id !== nodeId) return null;
455→    if (driverEvent?.kind !== 'driver.recorded' || driverEvent.payload?.kind !== 'integration.completed') return null;
456→    if (artifactEvent?.kind !== 'artifact.registered' || artifactEvent.payload?.taskId !== taskId || artifactEvent.payload?.accepted !== true) return null;
