110→/**
111→ * Re-derive the truth of a worker's result.
112→ * @param {object} task
113→ * @param {object} result
114→ * @param {{dir:string, sha:string, cleanup:() => Promise<void>}} sandbox
115→ * @param {{baseSandbox?: object, requireRedGreen?: boolean, requireCoverage?: boolean, requireMutation?: boolean, log?: object, worker?: string}} [opts]
116→ * @returns {Promise<object>} Verdict
117→ * @throws {SameWorktreeError}
118→ */
119→export async function verify(task, result, sandbox, opts = {}) {
120→  if (!('workerWorktreeDir' in task) || task.workerWorktreeDir == null) {
121→    throw new Error(
122→      'verify: task.workerWorktreeDir is required (D6 — the freshness guard is mandatory, not opt-in; '
123→      + 'omitting it silently disarms Invariant R1)',
124→    );
125→  }
126→  if (task.workerWorktreeDir === sandbox.dir) {
127→    throw new SameWorktreeError(
128→      `verify: sandbox.dir (${sandbox.dir}) equals task.workerWorktreeDir — refusing to trust-gate a worker's own worktree (R1)`,
129→    );
130→  }
131→
132→  const timeoutMs = task.verification.timeoutMs ?? 120000;
133→
134→  const start = Date.now();
135→  const resultRun = await runCommand(task.verification.command, sandbox.dir, timeoutMs);
136→  const durationMs = Date.now() - start;
137→
138→  const observedExit = resultRun.timedOut ? null : resultRun.exitCode;
139→  const claimedExit = result?.verification?.claimedExit ?? null;
140→  // A worker that makes no exit claim (a subprocess adapter that doesn't run its own
141→  // verification passes claimedExit=null) hasn't "diverged" — there is nothing to
142→  // diverge from. Only a claim that contradicts the hub's observation is a divergence.
143→  const hadClaim = claimedExit !== null;
144→  const matchesClaim = !hadClaim || observedExit === claimedExit;
145→  const passed = observedExit === task.verification.expectExit;
146→
147→  let redGreen = null;
148→  let baseExit = null;
149→  if (opts.baseSandbox) {
150→    const baseRun = await runCommand(task.verification.command, opts.baseSandbox.dir, timeoutMs);
151→    baseExit = baseRun.timedOut ? null : baseRun.exitCode;
152→    redGreen = passed && baseExit !== task.verification.expectExit;
153→  }
154→
155→  let coverageOfChange = null;
156→  let uncoveredChangedLines = [];
157→  let coverageNote = '';
158→  const hasChangedLines = task.changedLines && Object.keys(task.changedLines).length > 0;
159→  if (task.verification.coverageCommand && passed && hasChangedLines) {
160→    const covRun = await runCommand(task.verification.coverageCommand, sandbox.dir, timeoutMs);
161→    try {
162→      const parsed = JSON.parse(covRun.output);
163→      const files = parsed.files ?? {};
164→      const uncovered = [];
165→      for (const [filePath, lineNumbers] of Object.entries(task.changedLines)) {
166→        const executed = new Set(files[filePath]?.executedLines ?? []);
167→        for (const ln of lineNumbers) {
168→          if (!executed.has(ln)) uncovered.push(`${filePath}:${ln}`);
169→        }
170→      }
171→      uncoveredChangedLines = uncovered;
172→      coverageOfChange = uncovered.length === 0;
173→    } catch {
174→      coverageOfChange = null;
175→      coverageNote = ' Coverage report parse failure (non-JSON or malformed stdout) — coverage signal dropped, primary verdict unaffected.';
176→    }
177→  }
178→
179→  let mutationStrength = null;
180→  let mutationPassed = null;
181→  let survivedMutants = [];
182→  let mutationNote = '';
183→  if (task.verification.mutationCommand && passed) {
184→    const mutationRun = await runCommand(task.verification.mutationCommand, sandbox.dir, timeoutMs);
185→    try {
186→      const parsed = JSON.parse(mutationRun.output);
187→      const killed = Number(parsed.killed);
188→      const total = Number(parsed.total);
189→      survivedMutants = Array.isArray(parsed.survived) ? parsed.survived : [];
190→      if (Number.isFinite(killed) && Number.isFinite(total) && total > 0 && killed >= 0 && killed <= total) {
191→        mutationStrength = killed / total;
192→        mutationPassed = survivedMutants.length === 0 && killed === total;
193→      }
194→    } catch {
195→      mutationNote = ' Mutation report parse failure — mutation signal unknown.';
196→    }
197→  }
198→
199→  let note;
200→  if (!matchesClaim) {
201→    note = `Diverged from claim: worker claimed exit ${claimedExit}, hub observed ${observedExit}`
202→      + `${resultRun.timedOut ? ' (timeout: verification command exceeded the deadline)' : ''}.`;
203→  } else if (resultRun.timedOut) {
204→    note = `Timeout: verification command exceeded ${timeoutMs}ms.`;
205→  } else if (passed && redGreen === false) {
206→    note = `PASS but not red->green: the check already passed before the change (base exit ${baseExit}).`;
207→  } else if (passed && coverageOfChange === false) {
208→    note = `PASS but undercovered: ${uncoveredChangedLines.length} changed line(s) never executed.`;
209→  } else if (passed && mutationPassed === false) {
210→    note = `PASS but mutation-weak: ${survivedMutants.length} mutant(s) survived.`;
211→  } else if (passed) {
212→    note = `PASS: observed exit ${observedExit} matches expected ${task.verification.expectExit}.`;
213→  } else {
214→    note = `FAIL: observed exit ${observedExit}, expected ${task.verification.expectExit}.`;
215→  }
216→  note += coverageNote;
217→  note += mutationNote;
218→
219→  const verdict = {
220→    reverified: true,
221→    observedExit,
222→    hadClaim,
223→    matchesClaim,
224→    passed,
225→    locus: 'fresh_sandbox',
226→    redGreen,
227→    baseExit,
228→    coverageOfChange,
229→    uncoveredChangedLines,
230→    mutationStrength,
231→    mutationPassed,
232→    survivedMutants,
233→    observedOutputTail: resultRun.output.slice(-4000),
234→    note,
235→    durationMs,
236→  };
237→
238→  if (opts.log) {
239→    opts.log.append({
240→      worker: opts.worker ?? task.id,
241→      harness: 'n/a',
242→      turnEpoch: 0,
243→      kind: 'verify.reverified',
244→      actor: 'policy',
245→      payload: verdict,
246→    });
247→  }
248→
249→  return verdict;
250→}
251→
252→/**
253→ * A verdict is trustworthy — and a result is safe to mark "done"/merge — iff the hub
254→ * itself observed a pass, AND (if required) the hardening checks that were requested
255→ * came back true, not merely non-false.
256→ * @param {object} verdict
257→ * @param {{requireRedGreen?: boolean, requireCoverage?: boolean}} [opts]
258→ * @returns {boolean}
259→ */
260→export function accept(verdict, opts = {}) {
261→  const { requireRedGreen = false, requireCoverage = false, requireMutation = false } = opts;
262→  if (!verdict.reverified || !verdict.passed) return false;
263→  if (requireRedGreen && verdict.redGreen !== true) return false;
264→  if (requireCoverage && verdict.coverageOfChange !== true) return false;
265→  if (requireMutation && verdict.mutationPassed !== true) return false;
266→  return true;
267→}
